/**
 * Translate a page content string into the active language.
 * Returns the original English text when there is no translation.
 */
export function translatePage(lang: LangCode, text?: string): string {
    if (!text) return text ?? '';
    if (lang === 'en') return text;
    return content[text]?.[lang] ?? text;
}

export default content;
